import math

RATES = {"fast hash, 10^10 guesses/s": 10**10, "slow hash, 10^4 guesses/s": 10**4}   # assumed rates
SECRETS = {"8 random lowercase letters": 26**8, "8 random printable ASCII": 94**8, "4 random words (7,776-word list)": 7776**4}

def pretty(seconds):
    for unit, size in (("years", 365 * 24 * 3600), ("days", 24 * 3600), ("hours", 3600), ("minutes", 60)):
        if seconds >= size:
            return f"{seconds / size:,.1f} {unit}"
    return f"{seconds:,.2f} seconds"

for secret, space in SECRETS.items():
    print(f"{secret} ({math.log2(space):.1f} bits)")
    for rate_name, rate in RATES.items():
        print(f"    {rate_name:30} average {pretty(space / 2 / rate)}")
